/*

XML Loader
--------------------------

Map the XML tree directly to a D3 tree, without any modifications.
Elements are displayed as tree nodes and the attributes are shown
in the tooltips.

*/
export function parseXml(str) {
    const parser = new DOMParser();
    const doc = parser.parseFromString(str, "text/xml");
    if (doc.querySelector("parsererror")) {
        throw new Error("XML parse failed");
    }
    return domNodeToXML(doc.documentElement);
}
function domNodeToXML(element) {
    const attrs = {};
    for (const attr of Array.from(element.attributes)) {
        attrs[attr.name] = attr.value;
    }
    const nodes = [];
    const textParts = [];
    for (const child of Array.from(element.childNodes)) {
        if (child.nodeType === 1) {
            // Node.ELEMENT_NODE
            nodes.push(domNodeToXML(child));
        }
        else if (child.nodeType === 3 || child.nodeType === 4) {
            // Node.TEXT_NODE or Node.CDATA_SECTION_NODE
            const text = child.textContent?.trim();
            if (text) {
                textParts.push(text);
            }
        }
    }
    const textContent = textParts.join("");
    return {
        tag: element.tagName,
        text: textContent || undefined,
        attrs: Object.keys(attrs).length > 0 ? attrs : undefined,
        nodes: nodes.length > 0 ? nodes : undefined,
    };
}
function convertXML(xml) {
    const tag = xml.tag;
    const text = xml.text;
    const properties = new Map();
    if (text)
        properties.set("~text", text);
    if (xml.attrs) {
        for (const key of Object.keys(xml.attrs)) {
            properties.set(key, xml.attrs[key]);
        }
    }
    const children = [];
    for (const child of xml.nodes ?? []) {
        children.push(convertXML(child));
    }
    return {
        name: tag,
        properties: properties,
        children: children,
    };
}
export const xmlPlanLoader = {
    format: "xml",
    matches: () => true,
    load(xml) {
        return { root: convertXML(xml) };
    },
};
